WHENEVER SQLERROR EXIT SQL.SQLCODE
SET HEADING OFF FEEDBACK OFF PAGESIZE 0 LINESIZE 32767 LONG 100000 TRIMSPOOL ON
ALTER SESSION SET CONTAINER=FREEPDB1;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_detallePedidoPedido','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_PEDIDOS t LEFT JOIN POLLERIA.PEDIDOS p ON p.ID=t.PEDIDO_ID WHERE t.PEDIDO_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_detallePedidoProducto','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_PEDIDOS t LEFT JOIN POLLERIA.PRODUCTOS p ON p.ID=t.PRODUCTO_ID WHERE t.PRODUCTO_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_productoCategoria','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.PRODUCTOS t LEFT JOIN POLLERIA.CATEGORIAS p ON p.ID=t.CATEGORIA_ID WHERE t.CATEGORIA_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_pedidoCliente','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.PEDIDOS t LEFT JOIN POLLERIA.CLIENTES p ON p.ID=t.CLIENTE_ID WHERE t.CLIENTE_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_entregaPedido','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.ENTREGAS t LEFT JOIN POLLERIA.PEDIDOS p ON p.ID=t.PEDIDO_ID WHERE t.PEDIDO_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_entregaRepartidor','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.ENTREGAS t LEFT JOIN POLLERIA.REPARTIDORES p ON p.ID=t.REPARTIDOR_ID WHERE t.REPARTIDOR_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_compraProveedor','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.COMPRAS t LEFT JOIN POLLERIA.PROVEEDORES p ON p.ID=t.PROVEEDOR_ID WHERE t.PROVEEDOR_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_detalleCompraCompra','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_COMPRAS t LEFT JOIN POLLERIA.COMPRAS p ON p.ID=t.COMPRA_ID WHERE t.COMPRA_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_detalleCompraInsumo','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_COMPRAS t LEFT JOIN POLLERIA.INSUMOS p ON p.ID=t.INSUMO_ID WHERE t.INSUMO_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_movimientoInsumo','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.MOVIMIENTOS_INVENTARIO t LEFT JOIN POLLERIA.INSUMOS p ON p.ID=t.INSUMO_ID WHERE t.INSUMO_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'huerfano_movimientoCompra','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.MOVIMIENTOS_INVENTARIO t LEFT JOIN POLLERIA.COMPRAS p ON p.ID=t.COMPRA_ID WHERE t.COMPRA_ID IS NOT NULL AND p.ID IS NULL)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'totalPedido','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.PEDIDOS p WHERE p.TOTAL <> (SELECT COALESCE(SUM(d.SUBTOTAL),0) FROM POLLERIA.DETALLE_PEDIDOS d WHERE d.PEDIDO_ID=p.ID))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'subtotalPedido','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_PEDIDOS WHERE SUBTOTAL<>ROUND(PRECIO_UNITARIO*CANTIDAD,2))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'totalCompra','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.COMPRAS c WHERE c.TOTAL<>(SELECT COALESCE(SUM(d.SUBTOTAL),0) FROM POLLERIA.DETALLE_COMPRAS d WHERE d.COMPRA_ID=c.ID))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'subtotalCompra','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.DETALLE_COMPRAS WHERE SUBTOTAL<>ROUND(CANTIDAD*COSTO_UNITARIO,2))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'stockNegativo','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.INSUMOS WHERE STOCK_ACTUAL<0)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'movimientoNegativo','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.MOVIMIENTOS_INVENTARIO WHERE STOCK_POSTERIOR<0 OR STOCK_ANTERIOR<0)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'aritmeticaMovimiento','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.MOVIMIENTOS_INVENTARIO WHERE STOCK_POSTERIOR<>STOCK_ANTERIOR+CASE WHEN TIPO='SALIDA' THEN -CANTIDAD ELSE CANTIDAD END)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'secuenciaMovimiento','inconsistencias' VALUE (SELECT COUNT(*) FROM (SELECT STOCK_ANTERIOR, LAG(STOCK_POSTERIOR,1,0) OVER(PARTITION BY INSUMO_ID ORDER BY ID) PREVIO FROM POLLERIA.MOVIMIENTOS_INVENTARIO) WHERE STOCK_ANTERIOR<>PREVIO)) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'stockUltimoMovimiento','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.INSUMOS i WHERE i.STOCK_ACTUAL<>COALESCE((SELECT m.STOCK_POSTERIOR FROM POLLERIA.MOVIMIENTOS_INVENTARIO m WHERE m.INSUMO_ID=i.ID ORDER BY m.ID DESC FETCH FIRST 1 ROW ONLY),0))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'sincronizacionDelivery','inconsistencias' VALUE (SELECT COUNT(*) FROM POLLERIA.ENTREGAS e JOIN POLLERIA.PEDIDOS p ON p.ID=e.PEDIDO_ID WHERE (e.ESTADO='ASIGNADO' AND p.ESTADO NOT IN('LISTO','DESPACHADO')) OR (e.ESTADO IN('EN_CAMINO','NO_ENTREGADO') AND p.ESTADO<>'DESPACHADO') OR (e.ESTADO='ENTREGADO' AND p.ESTADO<>'ENTREGADO'))) FROM DUAL;
SELECT JSON_OBJECT('comprobacion' VALUE 'restriccionesDeshabilitadas','inconsistencias' VALUE (SELECT COUNT(*) FROM ALL_CONSTRAINTS WHERE OWNER='POLLERIA' AND (STATUS<>'ENABLED' OR VALIDATED<>'VALIDATED'))) FROM DUAL;
SELECT JSON_OBJECT('tabla' VALUE TABLE_NAME,'tipo' VALUE CONSTRAINT_TYPE,'cantidad' VALUE COUNT(*)) FROM ALL_CONSTRAINTS WHERE OWNER='POLLERIA' GROUP BY TABLE_NAME,CONSTRAINT_TYPE ORDER BY TABLE_NAME,CONSTRAINT_TYPE;
SELECT JSON_OBJECT('tabla' VALUE TABLE_NAME) FROM ALL_TABLES WHERE OWNER='POLLERIA' ORDER BY TABLE_NAME;
EXIT
